fn loss(data:&str){let mut child=Command::new("perf").args(["script","-D","-i",data]).stdout(Stdio::piped()).spawn().unwrap();let mut lines=0;let mut lost=vec![];for line in BufReader::new(child.stdout.take().unwrap()).lines(){let line=line.unwrap();lines+=1;if line.contains("PERF_RECORD_LOST"){lost.push(line);}}assert!(child.wait().unwrap().success());println!("{}",json!({"raw_lines":lines,"lost_records":lost,"zero_lost":lost.is_empty()}));}
