let mut cells=BTreeMap::new();for(k,v)in&rows{assert_eq!(v.len(),31);for(b,r)in v.iter().enumerate(){assert_eq!(r["block"],b);}cells.insert(k.clone(),json!({"median_ns":median(&v.iter().map(|v|v["result"]["ns"].as_f64().unwrap()).collect::<Vec<_>>()),"blocks":v}));}let mut pairs=BTreeMap::new();let mut checks=BTreeMap::new();for p in PATTERNS{for(a,b)in[("off","frozen"),("on","off"),("on","frozen")]{let ratios=(0..31).map(|i|rows[&format!("{p}/{a}")][i]["result"]["ns"].as_f64().unwrap()/rows[&format!("{p}/{b}")][i]["result"]["ns"].as_f64().unwrap()).collect::<Vec<_>>();let v=rank(&ratios);let pass=if a=="off"{v["low"].as_f64().unwrap()>=1./1.03&&v["high"].as_f64().unwrap()<=1.03}else{v["high"].as_f64().unwrap()<=1.03};checks.insert(format!("{p}/{a}/{b}/nonreg_or_cal"),pass);if a=="on"&&p=="final"{checks.insert(format!("final/{a}/{b}/gain"),v["high"].as_f64().unwrap()<1.&&v["wins"].as_u64().unwrap()>=21);}pairs.insert(format!("{p}/{a}/{b}"),v);}}
